import {Head,Link} from '@inertiajs/vue3';import AdminLayout from '../../../../../CORE/Resources/js/Layouts/AdminLayout.vue';import {Button} from '@/components/ui/button';import DataTable,{type DataTableColumn} from '../../../../../CORE/Resources/js/Components/DataTable.vue';import type {Paginator} from '../../../../../CORE/Resources/js/types';
